.gh-badge { display: inline-block; padding: 3px 10px; border-radius: 999px; background-color: #fdd700; color: #16212b; font-size: 12px; font-weight: 700; }
/* Legacy / editor classes so older template bodies inherit the brand */
.gh-content a.button, .gh-content a.btn, .gh-content a.btn-primary { display: inline-block; padding: 12px 22px; background-color: #c5386f; color: #ffffff !important; border-radius: 8px; text-decoration: none; }
#templateContainer, #templateBody, .bodyContent { background-color: transparent; border: 0; width: 100%; }
