UPDATE tblemailtemplates SET subject = 'Reset your GlobalHostia password', plaintext = 0,
  message = '<h1 style="margin:0 0 14px;font-family:Manrope,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;font-size:26px;line-height:1.25;font-weight:800;color:#16212b;">Reset your password</h1>
<p style="margin:0 0 16px;">Hi {$client_first_name},</p>
<p style="margin:0 0 16px;">We received a request to reset the password for your GlobalHostia account. Use the button below to choose a new one. The link works once and expires shortly.</p>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin:6px 0 24px;"><tr><td align="left"><table role="presentation" cellpadding="0" cellspacing="0" border="0" class="gh-btn" style="border-collapse:separate;"><tr><td align="center" bgcolor="#c5386f" style="background-color:#c5386f;border:1px solid #c5386f;border-radius:8px;mso-padding-alt:12px 22px;"><a href="{$pw_reset_url}" target="_blank" style="display:inline-block;padding:12px 22px;font-family:Inter,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;font-size:15px;font-weight:600;line-height:1.2;color:#ffffff;text-decoration:none;border-radius:8px;"><span class="gh-gm-s"><span class="gh-gm-d">Choose a new password</span></span></a></td></tr></table></td></tr></table>
<p class="gh-small" style="margin:0 0 16px;font-size:13px;line-height:1.55;color:#5a6774;">If the button does not work, copy this link into your browser:<br><span class="gh-code" style="word-break:break-all;">{$pw_reset_url}</span></p>
<p class="gh-small" style="margin:0 0 16px;font-size:13px;line-height:1.55;color:#5a6774;">Did not ask for this? You can ignore this email; your password stays the same. If you keep getting these, contact us at <a href="mailto:support@globalhostia.com">support@globalhostia.com</a>.</p>
<p style="margin:0 0 16px;">Thanks for choosing GlobalHostia,<br><strong>The GlobalHostia Team</strong></p>'
WHERE name = 'Password Reset Validation' AND type <> 'admin' AND (language = '' OR language IS NULL);

