<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" class="gh-panel" style="background-color:#f6f7f9;border:1px solid #e6e9ee;border-radius:12px;margin:0 0 20px;"><tr><td style="padding:14px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" class="gh-kv"><tr><td class="gh-k" width="38%" style="padding:7px 12px 7px 0;color:#5a6774;font-size:14px;vertical-align:top;">Ticket</td><td class="gh-v" style="padding:7px 0;color:#16212b;font-size:15px;font-weight:600;vertical-align:top;word-break:break-word;">#{$ticket_id}</td></tr><tr><td class="gh-k" width="38%" style="padding:7px 12px 7px 0;color:#5a6774;font-size:14px;vertical-align:top;">Subject</td><td class="gh-v" style="padding:7px 0;color:#16212b;font-size:15px;font-weight:600;vertical-align:top;word-break:break-word;">{$ticket_subject}</td></tr>{if $ticket_department}<tr><td class="gh-k" width="38%" style="padding:7px 12px 7px 0;color:#5a6774;font-size:14px;vertical-align:top;">Department</td><td class="gh-v" style="padding:7px 0;color:#16212b;font-size:15px;font-weight:600;vertical-align:top;word-break:break-word;">{$ticket_department}</td></tr>{/if}{if $ticket_priority}<tr><td class="gh-k" width="38%" style="padding:7px 12px 7px 0;color:#5a6774;font-size:14px;vertical-align:top;">Priority</td><td class="gh-v" style="padding:7px 0;color:#16212b;font-size:15px;font-weight:600;vertical-align:top;word-break:break-word;">{$ticket_priority}</td></tr>{/if}{if $ticket_status}<tr><td class="gh-k" width="38%" style="padding:7px 12px 7px 0;color:#5a6774;font-size:14px;vertical-align:top;">Status</td><td class="gh-v" style="padding:7px 0;color:#16212b;font-size:15px;font-weight:600;vertical-align:top;word-break:break-word;">{$ticket_status}</td></tr>{/if}</table></td></tr></table>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin:6px 0 24px;"><tr><td align="left"><table role="presentation" cellpadding="0" cellspacing="0" border="0" class="gh-btn" style="border-collapse:separate;"><tr><td align="center" bgcolor="#c5386f" style="background-color:#c5386f;border:1px solid #c5386f;border-radius:8px;mso-padding-alt:12px 22px;"><a href="{$ticket_link}" target="_blank" style="display:inline-block;padding:12px 22px;font-family:Inter,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;font-size:15px;font-weight:600;line-height:1.2;color:#ffffff;text-decoration:none;border-radius:8px;"><span class="gh-gm-s"><span class="gh-gm-d">View your ticket</span></span></a></td></tr></table></td></tr></table>
<p class="gh-small" style="margin:0 0 16px;font-size:13px;line-height:1.55;color:#5a6774;">To add details, simply reply to this email and keep the ticket number in the subject.</p>
<p style="margin:0 0 16px;">Thanks for choosing GlobalHostia,<br><strong>The GlobalHostia Team</strong></p>'
WHERE name = 'Support Ticket Opened' AND type <> 'admin' AND (language = '' OR language IS NULL);

