<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin:6px 0 24px;"><tr><td align="left"><table role="presentation" cellpadding="0" cellspacing="0" border="0" class="gh-btn" style="border-collapse:separate;"><tr><td align="center" bgcolor="#c5386f" style="background-color:#c5386f;border:1px solid #c5386f;border-radius:8px;mso-padding-alt:12px 22px;"><a href="{$ticket_link}" target="_blank" style="display:inline-block;padding:12px 22px;font-family:Inter,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;font-size:15px;font-weight:600;line-height:1.2;color:#ffffff;text-decoration:none;border-radius:8px;"><span class="gh-gm-s"><span class="gh-gm-d">View &amp; reply</span></span></a></td></tr></table></td></tr></table>
