-- Support Ticket Auto Close Notification  (Ticket closed after no reply)
UPDATE tblemailtemplates SET subject = '[Ticket ID: {$ticket_id}] Closed: {$ticket_subject}', plaintext = 0,
  message = '<h1 style="margin:0 0 14px;font-family:Manrope,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;font-size:26px;line-height:1.25;font-weight:800;color:#16212b;">Your ticket has been closed</h1>
<p style="margin:0 0 16px;">Hi {$client_name},</p>
<p style="margin:0 0 16px;">We have not heard back for a while, so ticket <strong>#{$ticket_id}</strong> ({$ticket_subject}) has been closed. We hope everything is working well.</p>
<p style="margin:0 0 16px;">Still need help? Reply to this email and the ticket reopens automatically, or open a new one.</p>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin:6px 0 24px;"><tr><td align="left"><table role="presentation" cellpadding="0" cellspacing="0" border="0" class="gh-btn" style="border-collapse:separate;"><tr><td align="center" bgcolor="#c5386f" style="background-color:#c5386f;border:1px solid #c5386f;border-radius:8px;mso-padding-alt:12px 22px;"><a href="{$ticket_link}" target="_blank" style="display:inline-block;padding:12px 22px;font-family:Inter,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;font-size:15px;font-weight:600;line-height:1.2;color:#ffffff;text-decoration:none;border-radius:8px;"><span class="gh-gm-s"><span class="gh-gm-d">View ticket</span></span></a></td></tr></table></td></tr></table>
<p style="margin:0 0 16px;">Thanks for choosing GlobalHostia,<br><strong>The GlobalHostia Team</strong></p>'
WHERE name = 'Support Ticket Auto Close Notification' AND type <> 'admin' AND (language = '' OR language IS NULL);

-- 4. Keep the admin ticket notifications switched on (content untouched)
UPDATE tblemailtemplates SET disabled = 0
WHERE type = 'admin' AND name IN ('Support Ticket Created', 'Support Ticket Response');

-- 5. Point every product at the right welcome email by product type
SET @t_hosting  = (SELECT id FROM tblemailtemplates WHERE name = 'Hosting Account Welcome Email' AND type <> 'admin' AND (language = '' OR language IS NULL) ORDER BY id LIMIT 1);
SET @t_reseller = COALESCE((SELECT id FROM tblemailtemplates WHERE name = 'Reseller Account Welcome Email' AND type <> 'admin' AND (language = '' OR language IS NULL) ORDER BY id LIMIT 1), @t_hosting);
SET @t_server   = (SELECT id FROM tblemailtemplates WHERE name = 'Dedicated/VPS Server Welcome Email' AND type <> 'admin' AND (language = '' OR language IS NULL) ORDER BY id LIMIT 1);
SET @t_other    = (SELECT id FROM tblemailtemplates WHERE name = 'Other Product/Service Welcome Email' AND type <> 'admin' AND (language = '' OR language IS NULL) ORDER BY id LIMIT 1);
SET @t_ssl      = COALESCE((SELECT id FROM tblemailtemplates WHERE name = 'SSL Certificate Configuration Required' AND type <> 'admin' AND (language = '' OR language IS NULL) ORDER BY id LIMIT 1), @t_other);

UPDATE tblproducts SET welcomeemail = @t_hosting  WHERE type = 'hostingaccount'  AND @t_hosting  IS NOT NULL;
UPDATE tblproducts SET welcomeemail = @t_reseller WHERE type = 'reselleraccount' AND @t_reseller IS NOT NULL;
UPDATE tblproducts SET welcomeemail = @t_server   WHERE type = 'server'          AND @t_server   IS NOT NULL AND NOT (LOWER(servertype) IN ('thesslstore','sslstore','gogetssl','digicertssl','resellerclubssl','enomssl','sectigo','ssl')
     OR (servertype = 'marketconnect' AND LOWER(configoption1) REGEXP 'ssl|digicert|geotrust|rapidssl|sectigo|comodo|thawte')
     OR (type = 'other' AND LOWER(name) REGEXP '(^|[^a-z])ssl([^a-z]|$)'));
UPDATE tblproducts SET welcomeemail = @t_other    WHERE type = 'other'           AND @t_other    IS NOT NULL AND NOT (LOWER(servertype) IN ('thesslstore','sslstore','gogetssl','digicertssl','resellerclubssl','enomssl','sectigo','ssl')
     OR (servertype = 'marketconnect' AND LOWER(configoption1) REGEXP 'ssl|digicert|geotrust|rapidssl|sectigo|comodo|thawte')
     OR (type = 'other' AND LOWER(name) REGEXP '(^|[^a-z])ssl([^a-z]|$)'));
UPDATE tblproducts SET welcomeemail = @t_ssl      WHERE @t_ssl IS NOT NULL AND (LOWER(servertype) IN ('thesslstore','sslstore','gogetssl','digicertssl','resellerclubssl','enomssl','sectigo','ssl')
     OR (servertype = 'marketconnect' AND LOWER(configoption1) REGEXP 'ssl|digicert|geotrust|rapidssl|sectigo|comodo|thawte')
     OR (type = 'other' AND LOWER(name) REGEXP '(^|[^a-z])ssl([^a-z]|$)'));

COMMIT;

-- 6. Check the result (phpMyAdmin shows these tables)
SELECT p.id, p.name, p.type, p.servertype, t.name AS welcome_email
FROM tblproducts p LEFT JOIN tblemailtemplates t ON t.id = p.welcomeemail
ORDER BY p.type, p.name;

SELECT id, type, name, subject, disabled FROM tblemailtemplates
WHERE (language = '' OR language IS NULL) AND (name IN ('Client Signup Email', 'Order Confirmation', 'Password Reset Validation', 'Password Reset Confirmation', 'Hosting Account Welcome Email', 'Reseller Account Welcome Email', 'Dedicated/VPS Server Welcome Email', 'Other Product/Service Welcome Email', 'SSL Certificate Configuration Required', 'Domain Registration Confirmation', 'Domain Transfer Initiated', 'Domain Renewal Confirmation', 'Invoice Created', 'Invoice Payment Confirmation', 'Invoice Payment Reminder', 'First Invoice Overdue Notice', 'Second Invoice Overdue Notice', 'Third Invoice Overdue Notice', 'Support Ticket Opened', 'Support Ticket Opened by Admin', 'Support Ticket Reply', 'Support Ticket Auto Close Notification') OR (type = 'admin' AND name IN ('Support Ticket Created', 'Support Ticket Response')))
ORDER BY type, name;
